const displayNames=new Map(INGREDIENT_DISPLAY_NAMES);
export const ingredientDisplayName=name=>displayNames.get(name)||name;
const ingredientFamily=value=>{const name=canonicalIngredient(value);return ingredientDisplayName(families.get(name)||name);};
export function ingredientSelections(value){
  if(typeof value!=='string'||!value.trim())return [];
  const parts=ingredientComposites.get(normalizeName(value))||[value];
  return [...new Set(parts.map(ingredientFamily))];
}
// 旧バージョンの保存値や単一名を返すAPIでは、複合原料の最初の構成成分に対応させる。
export function ingredientSelection(value){
  return ingredientSelections(value)[0]??canonicalIngredient(value);
}
export function matchesIngredientSelection(value,selection){
  return Boolean(selection&&selection!=='none'&&ingredientSelections(value).includes(ingredientSelection(selection)));
}

const prefixes=[
  ['温泉水','おんせんすい'],['加水分解','かすいぶんかい'],['海シルト','かいしると'],
  ['含水','がんすい'],['結晶','けっしょう'],['酵母','こうぼ'],['酢酸','さくさん'],
  ['酸化','さんか'],['植物性','しょくぶつせい'],['水添','すいてん'],['水溶性','すいようせい'],
  ['炭酸','たんさん'],['炭','すみ'],['窒素','ちっそ'],['二酸化','にさんか'],
  ['乳酸','にゅうさん'],['濃','のう'],['変性','へんせい'],['無水','むすい'],
  ['油溶性','ゆようせい'],['卵黄','らんおう'],['流動','りゅうどう'],['α','あるふぁ'],
];
const letters=['えー','びー','しー','でぃー','いー','えふ','じー','えいち','あい','じぇー','けー','える','えむ','えぬ','おー','ぴー','きゅー','あーる','えす','てぃー','ゆー','ぶい','だぶりゅー','えっくす','わい','ぜっと'];
const numbers={'2':'に','3':'さん','4':'よん','10':'じゅう'};
const collator=new Intl.Collator('ja',{numeric:true});
export function ingredientReading(name){
  const common={'水':'みず','精製水':'せいせいすい','常水':'じょうすい','香料':'こうりょう','黄酸化鉄':'おうさんかてつ','黒酸化鉄':'くろさんかてつ'};
  if(common[name])return common[name];
  let value=name.normalize('NFKC');
  for(const [word,reading] of [['水酸化','すいさんか'],['塩化','えんか'],['硫酸','りゅうさん'],['リン酸','りんさん'],['酸化鉄','さんかてつ']])if(value.startsWith(word)){value=reading+value.slice(word.length);break;}
  const prefix=prefixes.find(([text])=>value.startsWith(text));
  if(prefix)value=prefix[1]+value.slice(prefix[0].length);
  return value.replace(/^\d+/,number=>numbers[number]||number)
    .replace(/^[A-Za-z]+/,word=>[...word.toUpperCase()].map(char=>letters[char.charCodeAt(0)-65]).join(''))
    .replace(/[ァ-ヶ]/g,char=>String.fromCharCode(char.charCodeAt(0)-0x60));
}
export const compareIngredients=(a,b)=>{
  const ar=ingredientReading(a),br=ingredientReading(b);
  const kana=value=>/^[ぁ-ん]/u.test(value);
  return Number(!kana(ar))-Number(!kana(br))||collator.compare(ar,br)||collator.compare(a,b);
};

export function ingredientChoices(catalog){
  const names=new Set();
  for(const product of catalog){
    if(product.archived)continue;
    for(const value of product.ingredients||[]){
      for(const name of ingredientSelections(value)){
        // 数値だけの断片や、説明文が混ざった欄を選択肢として表示しない。
        if(typeof name!=='string' || !/[A-Za-zぁ-んァ-ヶ一-龯]/u.test(name) || /[。\r\n]|(?:エキス|成分)は/.test(name))continue;
        names.add(name);
      }
    }
  }
  return ['none',...[...names].sort(compareIngredients)];
}
